import * as vm from "vm";
import { logger } from "./logger";
import { recallIngestedKnowledge } from "./ingested-recall";
import { computeLunarData, computeSolarData } from "./sovereign-astro";
import { isAdminTokenConfigured } from "./sovereign-session";
import type { OwnerSessionDecision } from "./sovereign-admin";

export interface ToolExecutionContext {
  ownerSession?: OwnerSessionDecision;
}

export interface ToolDefinition {
  name: string;
  description: string;
  parameters: Record<string, { type: string; description?: string; required?: boolean }>;
  handler: (args: Record<string, unknown>, ctx?: ToolExecutionContext) => Promise<unknown> | unknown;
}

const PRIVILEGED_TOOLS = new Set(["mint_admin_sigil", "convene_grand_council_universalis"]);

export function isPrivilegedTool(name: string): boolean {
  return PRIVILEGED_TOOLS.has(name);
}

export function publicToolResult(name: string, result: unknown): unknown {
  if (!isPrivilegedTool(name)) return result;
  if (!result || typeof result !== "object") return { status: "refused" };
  const src = result as Record<string, unknown>;
  const out: Record<string, unknown> = {};
  if (typeof src.ok === "boolean") out.ok = src.ok;
  if (src.status === "ready" || src.status === "refused") out.status = src.status;
  if (src.error === "unauthenticated" || src.error === "sovereign-unconfigured") out.error = src.error;
  return out;
}

function privilegedRefusal(ctx?: ToolExecutionContext): "sovereign-unconfigured" | "unauthenticated" | null {
  if (!isAdminTokenConfigured()) return "sovereign-unconfigured";
  if (!ctx?.ownerSession?.ok) return "unauthenticated";
  return null;
}

export interface ToolCall {
  name: string;
  arguments: Record<string, unknown>;
}

export interface ToolInvocationResult {
  name: string;
  ok: boolean;
  result?: unknown;
  error?: string;
  durationMs: number;
}

const registry = new Map<string, ToolDefinition>();

export function registerTool(def: ToolDefinition): void {
  registry.set(def.name, def);
}

export function listTools(): ToolDefinition[] {
  return Array.from(registry.values());
}

export function getOpenAIToolSchemas(): Array<Record<string, unknown>> {
  return listTools().map((t) => {
    const properties: Record<string, unknown> = {};
    const required: string[] = [];
    for (const [k, v] of Object.entries(t.parameters)) {
      properties[k] = { type: v.type, description: v.description ?? "" };
      if (v.required) required.push(k);
    }
    return {
      type: "function",
      function: {
        name: t.name,
        description: t.description,
        parameters: { type: "object", properties, required },
      },
    };
  });
}

export async function invokeTool(call: ToolCall, ctx?: ToolExecutionContext): Promise<ToolInvocationResult> {
  const start = Date.now();
  const tool = registry.get(call.name);
  if (!tool) {
    return { name: call.name, ok: false, error: `unknown tool: ${call.name}`, durationMs: 0 };
  }
  if (isPrivilegedTool(call.name)) {
    const refusal = privilegedRefusal(ctx);
    if (refusal) {
      return {
        name: call.name,
        ok: false,
        error: refusal,
        result: { ok: false, status: "refused", error: refusal },
        durationMs: 0,
      };
    }
  }
  try {
    const result = await tool.handler(call.arguments || {}, ctx);
    return { name: call.name, ok: true, result, durationMs: Date.now() - start };
  } catch (err) {
    return { name: call.name, ok: false, error: (err as Error).message, durationMs: Date.now() - start };
  }
}

export async function runToolLoop(
  calls: ToolCall[],
  opts: { maxParallel?: number; ownerSession?: OwnerSessionDecision } = {},
): Promise<ToolInvocationResult[]> {
  const max = opts.maxParallel ?? 4;
  const ctx = opts.ownerSession ? { ownerSession: opts.ownerSession } : undefined;
  const results: ToolInvocationResult[] = [];
  for (let i = 0; i < calls.length; i += max) {
    const batch = calls.slice(i, i + max);
    const out = await Promise.all(batch.map((call) => invokeTool(call, ctx)));
    results.push(...out);

/** Public no-login hosts. Cookie import stays off. See NOTICE for the MIT adapter idea. */
export const ALLOWED_HOSTS = ["hn.algolia.com"];

export function importCookies() {
  throw new Error("cookie import is disabled");
}

function refused(url) {
  if (/login|signin|sign-in|oauth|cookie/i.test(`${url.pathname}${url.search}`)) return "login refused";
  if (!ALLOWED_HOSTS.includes(url.host)) return "host refused";
  return "";
}

export async function searchAllowlist(urlString, fetchFn) {
  const url = new URL(urlString);
  const reason = refused(url);
  if (reason) return { ok: false, reason };
  const response = await fetchFn(url.toString(), { headers: { accept: "application/json" } });
  const body = await response.json();
  const hits = Array.isArray(body.hits)
    ? body.hits.map((hit) => ({ title: String(hit.title ?? ""), url: String(hit.url ?? "") }))
    : [];
  return { ok: true, hits };
}

export function detectIntents(query: string): ToolCall[] {
  const calls: ToolCall[] = [];
  for (const { pattern, toToolCall } of INTENT_PATTERNS) {
    const m = query.match(pattern);
    if (m) {
      const c = toToolCall(m, query);
      if (c) calls.push(c);
    }
  }
  return calls;
}

// ---- Built-in tools ----
registerTool({
  name: "calculator",
  description: "Evaluate a numeric arithmetic expression. Supports + - * / ** ( ).",
  parameters: { expression: { type: "string", description: "Arithmetic expression", required: true } },
  handler: ({ expression }) => {
    const expr = String(expression || "").replace(/[×x]/gi, "*").replace(/÷/g, "/").replace(/\^/g, "**");
    if (!/^[\d+\-*/().\s]+$/.test(expr)) throw new Error("invalid characters in expression");
    const ctx = vm.createContext({ result: undefined });
    vm.runInContext(`result = (${expr})`, ctx, { timeout: 200 });
    return { expression: expr, value: ctx.result };
  },
});

registerTool({
  name: "datetime",
  description: "Return the current server date/time in ISO + human formats.",
  parameters: {},
  handler: () => {
    const d = new Date();
    return { iso: d.toISOString(), local: d.toString(), utc: d.toUTCString(), unix: Math.floor(d.getTime() / 1000) };
  },
});

const UNIT_FACTORS: Record<string, number> = {
  m: 1, km: 1000, cm: 0.01, mm: 0.001, mi: 1609.344, ft: 0.3048, in: 0.0254, yd: 0.9144,
  g: 1, kg: 1000, mg: 0.001, lb: 453.592, oz: 28.3495,
  s: 1, min: 60, hr: 3600, hour: 3600, day: 86400,
  l: 1, ml: 0.001, gal: 3.78541,
};
registerTool({
  name: "unit_convert",
  description: "Convert between common units (length, mass, time, volume).",
  parameters: {
    value: { type: "number", required: true },
    from: { type: "string", required: true },
    to: { type: "string", required: true },
  },
  handler: ({ value, from, to }) => {
    const f = UNIT_FACTORS[String(from).toLowerCase()];
    const t = UNIT_FACTORS[String(to).toLowerCase()];
    if (!f || !t) throw new Error(`unsupported unit: ${from} -> ${to}`);
    const meters = Number(value) * f;
    return { value: meters / t, unit: to };
  },
});

registerTool({
  name: "astronomy",
  description: "Compute live lunar + solar data.",
  parameters: {},
  handler: () => {
    const lunar = computeLunarData();
    const solar = computeSolarData();
    return { lunar, solar };
  },
});

registerTool({
  name: "knowledge_lookup",
  description: "Search the sovereign ingested knowledge corpus.",
  parameters: {
    query: { type: "string", required: true },
    limit: { type: "number" },
  },
  handler: async ({ query, limit }) => {
    const matches = await recallIngestedKnowledge(String(query), Number(limit) || 5);
    return { matches };
  },
});

registerTool({
  name: "mint_admin_sigil",
  description: "Report whether the owner session can reach the admin sigil tool. Does not read or return chart data.",
  parameters: {},
  handler: (_args, ctx) => {
    const refusal = privilegedRefusal(ctx);
    if (refusal) return { ok: false, status: "refused", error: refusal };
    return { ok: true, status: "ready" };
  },
});

registerTool({
  name: "convene_grand_council_universalis",
  description: "Report whether the owner session can reach the council tool. Does not read or return chart data.",
  parameters: {},
  handler: (_args, ctx) => {
    const refusal = privilegedRefusal(ctx);
    if (refusal) return { ok: false, status: "refused", error: refusal };
    return { ok: true, status: "ready" };
  },
});

registerTool({
  name: "code_eval",
  description: "Execute a sandboxed JavaScript expression and return its value (no I/O, 200ms timeout).",
  parameters: { code: { type: "string", required: true } },
  handler: ({ code }) => {
    const src = String(code || "");
    if (/require|import|process|fetch|fs|child_process|eval\s*\(/.test(src)) {
      throw new Error("disallowed identifier in code_eval");
    }
    const ctx = vm.createContext({ result: undefined, Math, Number, Array, Object, String, JSON });
    vm.runInContext(`result = (function(){ ${src.includes("return") ? src : "return (" + src + ")"} })()`, ctx, { timeout: 200 });
    return { value: ctx.result };
  },
});

logger.info({ tools: listTools().map((t) => t.name) }, "ToolRegistry: built-ins registered");

