export async function fetchUNData(datasetId = "DP_LCN_HOUS.A", limit = 5): Promise<NormalizedItem[]> {
  const url = `https://unstats.un.org/SDGAPI/v1/sdg/Indicator/List?pageSize=${limit}`;
